(function () {
  function reportDiag(stage, extra) {
    try {
      $.post('this.php', {
        action: 'pushDiag',
        stage: stage,
        extra: String(extra || ''),
        platform: String((window.Capacitor && window.Capacitor.getPlatform && window.Capacitor.getPlatform()) || 'web'),
        alumno_token: String(localStorage.getItem('cobaed_tkn') || '')
      });
    } catch (e) {}
  }

  if (!window.Capacitor || !window.Capacitor.Plugins || !window.Capacitor.Plugins.PushNotifications) {
    reportDiag('plugin_missing', navigator.userAgent || '');
    return;
  }

  var PushNotifications = window.Capacitor.Plugins.PushNotifications;
  var deviceIdKey = 'cobaed_push_device_id';

  function getDeviceId() {
    var current = localStorage.getItem(deviceIdKey);
    if (current) return current;
    var generated = 'dev_' + Math.random().toString(36).slice(2, 10) + Date.now().toString(36);
    localStorage.setItem(deviceIdKey, generated);
    return generated;
  }

  function registerTokenOnBackend(pushToken) {
    var alumnoToken = String(localStorage.getItem('cobaed_tkn') || '').trim();
    if (!alumnoToken || !pushToken) {
      reportDiag('token_not_sent_missing_alumno_or_token', alumnoToken ? 'missing_push_token' : 'missing_alumno_token');
      return;
    }

    var payload = {
      action: 'registerPushToken',
      alumno_token: alumnoToken,
      push_token: pushToken,
      device_id: getDeviceId(),
      platform: String((window.Capacitor && window.Capacitor.getPlatform && window.Capacitor.getPlatform()) || 'unknown')
    };

    $.post('this.php', payload, function (resp) {
      if (!resp || !resp.ok) {
        reportDiag('register_backend_fail', (resp && resp.message) ? resp.message : 'no_ok_response');
        console.warn('No se pudo registrar push token en backend');
      } else {
        reportDiag('register_backend_ok', payload.device_id);
      }
    }, 'json').fail(function (xhr) {
      reportDiag('register_backend_http_fail', xhr.status);
      console.warn('Error registrando push token:', xhr.status);
    });
  }

  function initPush() {
    PushNotifications.addListener('registration', function (token) {
      if (token && token.value) {
        reportDiag('registration_ok', token.value.slice(0, 12));
        registerTokenOnBackend(token.value);
      } else {
        reportDiag('registration_empty_token', '');
      }
    });

    PushNotifications.addListener('registrationError', function (err) {
      reportDiag('registration_error', (err && (err.error || err.message)) ? (err.error || err.message) : 'unknown');
      console.error('Error registro Push:', err);
    });

    PushNotifications.addListener('pushNotificationReceived', function (notification) {
      console.log('Push recibido:', notification);
    });

    PushNotifications.checkPermissions().then(function (permStatus) {
      reportDiag('check_permissions', JSON.stringify(permStatus || {}));
      if (permStatus.receive === 'prompt') {
        reportDiag('request_permissions', 'prompt');
        return PushNotifications.requestPermissions();
      }
      return permStatus;
    }).then(function (permStatus) {
      reportDiag('permissions_result', JSON.stringify(permStatus || {}));
      if (permStatus.receive !== 'granted') {
        reportDiag('permissions_not_granted', permStatus.receive || 'unknown');
        return;
      }
      reportDiag('register_called', 'ok');
      return PushNotifications.register();
    }).catch(function (err) {
      reportDiag('init_push_error', (err && (err.message || err.error)) ? (err.message || err.error) : 'unknown');
      console.error('Error inicializando push:', err);
    });
  }

  initPush();
})();
